// The "shared" library holds the note/strumline atlases, characters and stage art. HTML5 Lime can only
// return images/text synchronously (Assets.getBitmapData / getText) for assets that were PRELOADED, so
// without preload:true the game fails with "Could not load spritesheet for note style: funkin".
// Mark every IMAGE/TEXT asset of the shared library as preload (audio stays lazy/async).
function buildSharedManifest(){
  if (sharedManifestJson) return sharedManifestJson;
  const m = JSON.parse(buildManifest());
  for (const a of m.assets) {
    if (typeof a.id === 'string' && a.id.startsWith('assets/shared/') && /^\.\.\/assets\/shared\//.test(a.path || '') && (a.type === 'IMAGE' || a.type === 'TEXT' || ((a.type === 'SOUND' || a.type === 'MUSIC') && /^\.\.\/assets\/shared\/(sounds\/|music\/gameplay\/|music\/breakfast)/.test(a.path)))) a.preload = true;
  }
  sharedManifestJson = JSON.stringify(m);
  return sharedManifestJson;
}
async function resolveManifest(name){
  // Every generated OpenFL library is backed by the same official asset tree.
  // This prevents song/stage libraries from stalling when their generated manifest is absent.
  const body = /^shared(\.json)?$/i.test(String(name).split('?')[0]) ? buildSharedManifest() : buildManifest();
  return new Response(body, {status:200, headers:{'Content-Type':'application/json; charset=utf-8','Cache-Control':'no-store'}});
}
